package com.inventra.backend.service; import com.inventra.backend.dto.*; import com.inventra.backend.model.*; import com.inventra.backend.repository.*; import org.springframework.stereotype.Service; import java.time.LocalDateTime; import java.util.*; @Service public class PurchaseOrderService {private final PurchaseOrderRepository repo;private final ProductRepository products;private final InventoryCoreService inv;public PurchaseOrderService(PurchaseOrderRepository r,ProductRepository p,InventoryCoreService i){repo=r;products=p;inv=i;}public PurchaseOrder create(PurchaseOrderRequest r){PurchaseOrder p=new PurchaseOrder();p.setPoNumber("PO-"+System.currentTimeMillis());p.setWarehouseId(r.warehouseId());p.setSupplierName(r.supplierName());List<PurchaseOrderItem> items=new ArrayList<>();for(PurchaseOrderItemRequest x:r.items()){products.findById(x.productId()).orElseThrow(()->new IllegalArgumentException("Product not found: "+x.productId()));items.add(new PurchaseOrderItem(x.productId(),x.quantity(),x.unitCost()));}p.setItems(items);p.setStatus(PurchaseOrderStatus.ORDERED);return repo.save(p);}public List<PurchaseOrder> all(){return repo.findAllByOrderByCreatedAtDesc();}public PurchaseOrder receive(String id){PurchaseOrder p=repo.findById(id).orElseThrow(()->new IllegalArgumentException("Purchase order not found"));if(p.getStatus()==PurchaseOrderStatus.CANCELLED||p.getStatus()==PurchaseOrderStatus.RECEIVED)throw new IllegalStateException("Purchase order cannot be received");for(PurchaseOrderItem i:p.getItems()){int remaining=i.getQuantity()-i.getReceivedQuantity();if(remaining>0){inv.receive(p.getWarehouseId(),i.getProductId(),remaining,p.getId(),"Purchase order received");i.setReceivedQuantity(i.getReceivedQuantity()+remaining);}}p.setStatus(PurchaseOrderStatus.RECEIVED);p.setUpdatedAt(LocalDateTime.now());return repo.save(p);} }
